class Solution {
  public int[][] minAbsDiff(int[][] grid, int k) {
    int m = grid.length, n = grid[0].length;
    int[][] ans = new int[m - k + 1][n - k + 1];
    int[] values = new int[k * k];
    for (int i = 0; i + k <= m; i++) {
      for (int j = 0; j + k <= n; j++) {
        int idx = 0;
        for (int r = i; r < i + k; r++) {
          for (int c = j; c < j + k; c++) values[idx++] = grid[r][c];
        }
        Arrays.sort(values);
        int best = Integer.MAX_VALUE;
        for (int t = 1; t < values.length; t++) {
          if (values[t] != values[t - 1]) best = Math.min(best, values[t] - values[t - 1]);
        }
        ans[i][j] = best == Integer.MAX_VALUE ? 0 : best;
      }
    }
    return ans;
  }
}
